C338_R = [("    for (const zf of [0.68, 0.3]) { const z = P.z0 + (P.z1 - P.z0) * zf, cx = (P.x0 + P.x1) / 2, ob = (bar, x, h = 0) => { const c = chParked(x, z, h, bar); c.tutS = P; };   // c335: 주차장 중간중간 작은 진지 둘 — 경찰차 하나 + 바리케이트 둘 (틈 있게), 그 뒤에 경찰 2 · 군인 2 (저격수 없음)\n      ob(true, cx + (zf > 0.5 ? -1.4 : 1.4)); ob(false, cx + (zf > 0.5 ? 1.9 : -1.9), Math.PI / 2);   /* c336: 좁아진 가운데 길 — 바리케이트 하나 + 세로로 선 경찰차 하나 (엇갈려 틈) */\n      for (const [t, dx] of [['police', -2.0], ['soldier', -0.7], ['soldier', 0.7], ['police', 2.0]]) { const c = man(P, t, cx + dx, z - 2.2); c.post = c.area; if (t === 'soldier') c.noMaster = true; enterNormal(c); } }\n    const LX = (Q.x0 + Q.x1) / 2, R1 = Q.z1, R0 = Q.z0, obst = (bar, x, z, h = 0) => { const c = chParked(x, z, h, bar); c.tutS = Q; return c; };\n    obst(true, LX - 1.1, R1 - 4.6); obst(true, LX + 1.4, R1 - 4.6); obst(false, LX - 1.9, R1 - 7.0, Math.PI / 2); obst(true, LX + 1.3, R1 - 7.0); obst(true, LX - 1.3, R1 - 9.8); obst(false, LX + 1.9, R1 - 9.8, Math.PI / 2);   /* c337: 철망 앞 진지 — 길 가운데로 모으고 늘림 (바리케이트 2 → 4 · 경찰차 2), 세 줄 엇갈림 */\n    for (const [t, dx, z] of [['police', -1.4, R1 - 5.8], ['police', 0.2, R1 - 5.9], ['soldier', 1.5, R1 - 5.8],\n      ['soldier', -2.0, R1 - 8.6], ['police', -0.5, R1 - 8.6], ['soldier', 1.0, R1 - 8.6], ['soldier', 2.3, R1 - 8.6],\n      ['soldier', -2.2, R1 - 11.3], ['police', -0.8, R1 - 11.3], ['soldier', 0.7, R1 - 11.3], ['police', 2.2, R1 - 11.3], ['soldier', 0, R1 - 12.4]]) {   // 장애물 줄마다 그 뒤에 (경찰 5 · 군인 7)\n      const c = man(Q, t, LX + dx, z); c.post = c.area; if (t === 'soldier') c.noMaster = true; enterNormal(c); }\n    { const spots = [];   // c337: 전체에 경찰 4 · 군인 3 더 — 주차장 가운데 길과 철망 앞 길 아무 데나 (서로 1칸 넘게 떨어져서)\n      for (const t of ['police', 'police', 'police', 'police', 'soldier', 'soldier', 'soldier']) { const inRoad = Math.random() < 0.3, S = inRoad ? Q : P; let x = 0, z = 0;\n        for (let k = 0; k < 200; k++) { x = inRoad ? LX + (Math.random() - 0.5) * 4.6 : P.x0 + 3.8 + Math.random() * (P.x1 - P.x0 - 7.6); z = inRoad ? R1 - 2 - Math.random() * 10.5 : P.z0 + 1.5 + Math.random() * (P.z1 - P.z0 - 7.5); if (spots.every(([a, b]) => Math.hypot(a - x, b - z) > 1.1) && bodies.every((q) => q.kind !== 'citizen' || Math.hypot(q.foot.x - x, q.foot.z - z) > 0.9)) break; }\n        spots.push([x, z]); const c = man(S, t, x, z); c.post = c.area; if (t === 'soldier') c.noMaster = true; enterNormal(c); } }\n    for (const dx of [-2.25, -0.75, 0.75, 2.25]) { const n = man(Q, 'sniper', LX + dx, R0 + 2.2, 0.4); n.post = n.area; enterNormal(n); }   // 맨 뒤 저격수 4", "    const cx = (P.x0 + P.x1) / 2, Z1 = P.z1, post = (S, t, x, z, r = 0.5) => { const c = man(S, t, x, z, r); c.post = c.area; if (t === 'soldier') c.noMaster = true; enterNormal(c); return c; };   // c338: 주차장 = 경찰차 진지 — 가로로 세운 경찰차 7대, 차마다 뒤에 경찰 2 (영화처럼 차 뒤에 숨어 대기), 중간 바리케이트 2 (뒤에 군인 2씩)\n    const pcar = (x, z) => { const c = chParked(x, z, 0, false); c.tutS = P; post(P, 'police', x - 0.55, z - 1.3); post(P, 'police', x + 0.55, z - 1.3); }, pbar = (x, z) => { const c = chParked(x, z, 0, true); c.tutS = P; post(P, 'soldier', x - 0.5, z - 1.3); post(P, 'soldier', x + 0.5, z - 1.3); };\n    pcar(cx - 1.4, Z1 - 5.0); pcar(cx + 1.4, Z1 - 5.0);\n    pcar(cx - 1.3, Z1 - 8.6); pbar(cx + 1.5, Z1 - 8.6); post(P, 'sniper', cx, Z1 - 10.4, 0.4);   // 저격수 1 (주차장 앞쪽)\n    pcar(cx - 1.4, Z1 - 12.2); pcar(cx + 1.4, Z1 - 12.2);\n    pcar(cx + 1.3, Z1 - 15.8); pbar(cx - 1.5, Z1 - 15.8); post(P, 'sniper', cx + 0.2, Z1 - 17.6, 0.4);   // 저격수 1 (주차장 뒤쪽)\n    pcar(cx, Z1 - 19.4);\n    const LX = (Q.x0 + Q.x1) / 2, R1 = Q.z1, R0 = Q.z0, obst = (x, z) => { const c = chParked(x, z, 0, true); c.tutS = Q; return c; };   // c338: 마지막 길목 = 바리케이트만 (6개, 세 줄 엇갈림) — 그 사이사이에 경찰 · 군인 · 저격수\n    obst(LX - 1.1, R1 - 4.6); obst(LX + 1.4, R1 - 4.6); obst(LX - 1.4, R1 - 7.2); obst(LX + 1.1, R1 - 7.2); obst(LX - 1.1, R1 - 9.8); obst(LX + 1.4, R1 - 9.8);\n    for (const [t, dx, z] of [['police', -1.6, R1 - 5.8], ['soldier', 0.1, R1 - 5.8], ['soldier', 1.7, R1 - 5.8], ['sniper', 0.9, R1 - 6.6],\n      ['soldier', -2.0, R1 - 8.4], ['police', -0.6, R1 - 8.4], ['soldier', 0.8, R1 - 8.4], ['soldier', 2.2, R1 - 8.4],\n      ['soldier', -2.2, R1 - 11.0], ['police', -0.8, R1 - 11.0], ['soldier', 0.7, R1 - 11.0], ['police', 2.2, R1 - 11.0], ['sniper', -0.5, R1 - 12.0],\n      ['soldier', -1.5, R1 - 13.2], ['police', 0.2, R1 - 13.2], ['soldier', 1.6, R1 - 13.2], ['soldier', 2.5, R1 - 12.4]]) post(Q, t, LX + dx, z, t === 'sniper' ? 0.4 : 0.5);   // 저격수 2 (길목 앞 · 뒤)"), ("g.fillStyle = B.type === 'lot' ? '#5f646b' :", "g.fillStyle = B.type === 'lot' ? '#9aa0a7' :   /* c338: 주차장 바닥 밝게 (사람이 잘 보이게) */")]
